#include "netflixnx.hpp"
#include <algorithm>
#include <cmath>
namespace nx {
static constexpr int C=8,V=5,R=2;
static SDL_Rect navR(int i){return{52+i*145,44,124,42};}
static SDL_Rect keyR(int i){return{70+(i%10)*112,205+(i/10)*72,96,54};}
static SDL_Rect profR(int i){return{178+i*235,245,180,180};}
static void f(SDL_Renderer*r,SDL_Rect q,Uint8 c){SDL_SetRenderDrawColor(r,c,c,c,255);SDL_RenderFillRect(r,&q);}
static bool h(int x,int y,SDL_Rect q){return x>=q.x&&x<q.x+q.w&&y>=q.y&&y<q.y+q.h;}
static SDL_Rect card(const AppState&s,int row,int col,bool z=false){int w=z?224:210,hh=z?128:118;int x=54+col*238-(int)s.scrollX[row],y=382+row*150;return{x-(w-210)/2,y-(hh-118)/2,w,hh};}
static void sync(AppState&s){for(int i=0;i<R;i++){int n=i==s.focusedRow?s.focusedCard:0;s.targetScrollX[i]=(float)std::max(0,(n-(V-1))*238);}}
void update(AppState&s,float dt){for(int i=0;i<R;i++){float d=s.targetScrollX[i]-s.scrollX[i];s.scrollX[i]+=d*std::min(1.f,dt*11.f);}s.focusPulse+=dt*4.f;}
static void section(AppState&s,int d){int v=(int)s.screen;s.screen=(Screen)((v+d+4)%4);s.focusedCard=s.focusedRow=0;s.view=View::Browse;sync(s);}
static void open(AppState&s){if(s.view==View::Profiles){s.view=View::Browse;return;}if(s.screen==Screen::Search&&s.view==View::Browse){if(s.searchLength<24)s.searchLength++;return;}if(s.screen==Screen::Settings&&s.view==View::Browse){s.view=View::Profiles;return;}if(s.view==View::Browse){s.view=View::Details;s.detailsAction=0;}else if(s.view==View::Details&&s.detailsAction==0){s.view=View::Player;s.playerPaused=false;}else if(s.view==View::Player)s.playerPaused=!s.playerPaused;}
static void back(AppState&s){if(s.screen==Screen::Search&&s.view==View::Browse&&s.searchLength){s.searchLength--;return;}if(s.view==View::Player)s.view=View::Details;else if(s.view==View::Details)s.view=View::Browse;else if(s.view==View::Profiles)s.view=View::Browse;}
void handleInput(AppState&s,PadState&p,SDL_Renderer*){u64 d=padGetButtonsDown(&p);if(d)s.lastInputTick=SDL_GetTicks();if(d&HidNpadButton_Plus){s.running=false;return;}if(d&HidNpadButton_B)back(s);
 if(s.view==View::Profiles){if(d&(HidNpadButton_Right|HidNpadButton_StickLRight))s.profile=std::min(3,s.profile+1);if(d&(HidNpadButton_Left|HidNpadButton_StickLLeft))s.profile=std::max(0,s.profile-1);}
 else if(s.view==View::Browse&&s.screen==Screen::Search){if(d&(HidNpadButton_Right|HidNpadButton_StickLRight))s.searchKey=std::min(29,s.searchKey+1);if(d&(HidNpadButton_Left|HidNpadButton_StickLLeft))s.searchKey=std::max(0,s.searchKey-1);if(d&(HidNpadButton_Down|HidNpadButton_StickLDown))s.searchKey=std::min(29,s.searchKey+10);if(d&(HidNpadButton_Up|HidNpadButton_StickLUp))s.searchKey=std::max(0,s.searchKey-10);}
 else if(s.view==View::Browse){if(d&(HidNpadButton_Right|HidNpadButton_StickLRight))s.focusedCard=std::min(C-1,s.focusedCard+1);if(d&(HidNpadButton_Left|HidNpadButton_StickLLeft))s.focusedCard=std::max(0,s.focusedCard-1);if(d&(HidNpadButton_Down|HidNpadButton_StickLDown))s.focusedRow=std::min(R-1,s.focusedRow+1);if(d&(HidNpadButton_Up|HidNpadButton_StickLUp))s.focusedRow=std::max(0,s.focusedRow-1);sync(s);}
 else if(s.view==View::Details){if(d&(HidNpadButton_Right|HidNpadButton_StickLRight))s.detailsAction=std::min(1,s.detailsAction+1);if(d&(HidNpadButton_Left|HidNpadButton_StickLLeft))s.detailsAction=std::max(0,s.detailsAction-1);}
 if(d&HidNpadButton_R)section(s,1);if(d&HidNpadButton_L)section(s,-1);if(d&HidNpadButton_A)open(s);
 HidTouchScreenState t{};hidGetTouchScreenStates(&t,1);bool td=t.count;if(td&&!s.touchWasDown){int x=t.touches[0].x,y=t.touches[0].y;if(s.view==View::Profiles){for(int i=0;i<4;i++)if(h(x,y,profR(i))){if(s.profile==i)open(s);else s.profile=i;}}else if(s.view==View::Browse){for(int i=0;i<4;i++)if(h(x,y,navR(i))){s.screen=(Screen)i;s.focusedCard=s.focusedRow=0;sync(s);}if(s.screen==Screen::Search){for(int i=0;i<30;i++)if(h(x,y,keyR(i))){s.searchKey=i;open(s);}}else for(int rr=0;rr<R;rr++)for(int cc=0;cc<C;cc++){SDL_Rect q=card(s,rr,cc);if(h(x,y,q)){if(s.focusedRow==rr&&s.focusedCard==cc)open(s);else{s.focusedRow=rr;s.focusedCard=cc;sync(s);}}}}else open(s);}s.touchWasDown=td;}
static void nav(SDL_Renderer*r,const AppState&s){f(r,{0,0,1280,105},10);for(int i=0;i<4;i++){SDL_Rect q=navR(i);f(r,q,i==(int)s.screen?54:24);if(i==(int)s.screen){SDL_SetRenderDrawColor(r,229,9,20,255);SDL_Rect l{q.x,q.y+49,q.w,4};SDL_RenderFillRect(r,&l);}}SDL_SetRenderDrawColor(r,229,9,20,255);SDL_Rect m{1185,34,30,50};SDL_RenderFillRect(r,&m);}
static void profiles(SDL_Renderer*r,const AppState&s){f(r,{0,0,1280,720},12);f(r,{430,105,420,30},210);for(int i=0;i<4;i++){SDL_Rect q=profR(i);if(i==s.profile){int e=6+(int)(2*std::sin(s.focusPulse));f(r,{q.x-e,q.y-e,q.w+2*e,q.h+2*e},238);}SDL_SetRenderDrawColor(r,35+i*24,60+i*14,82+i*18,255);SDL_RenderFillRect(r,&q);f(r,{q.x+28,q.y+q.h+26,124,10},125);}f(r,{470,540,340,14},80);}
static void browse(SDL_Renderer*r,const AppState&s){nav(r,s);for(int y=105;y<355;y+=10){Uint8 c=(Uint8)(31-(y-105)/18);SDL_SetRenderDrawColor(r,c,c,c+3,255);SDL_Rect b{0,y,1280,10};SDL_RenderFillRect(r,&b);}f(r,{54,145,440,22},205);f(r,{54,181,330,13},100);f(r,{54,205,390,13},80);f(r,{54,248,154,52},220);f(r,{222,248,154,52},68);for(int rr=0;rr<R;rr++){f(r,{54,352+rr*150,170,12},125);for(int cc=0;cc<C;cc++){bool z=rr==s.focusedRow&&cc==s.focusedCard;SDL_Rect q=card(s,rr,cc,z);if(q.x>1280||q.x+q.w<0)continue;if(z)f(r,{q.x-4,q.y-4,q.w+8,q.h+8},245);SDL_SetRenderDrawColor(r,43+rr*12+cc*5,45+cc*4,52+rr*10,255);SDL_RenderFillRect(r,&q);f(r,{q.x+12,q.y+q.h-31,q.w-50,7},155);f(r,{q.x+12,q.y+q.h-17,q.w-88,5},92);}}}
static void search(SDL_Renderer*r,const AppState&s){nav(r,s);f(r,{70,130,1100,54},28);f(r,{88,151,std::min(900,24+s.searchLength*32),12},150);for(int i=0;i<30;i++){SDL_Rect q=keyR(i);if(i==s.searchKey)f(r,{q.x-4,q.y-4,q.w+8,q.h+8},235);f(r,q,50+(i%3)*7);f(r,{q.x+35,q.y+20,26,12},150);}f(r,{70,450,240,14},110);for(int i=0;i<4;i++)f(r,{70+i*285,485,260,146},45+i*8);}
static void details(SDL_Renderer*r,const AppState&s){f(r,{0,0,1280,430},31);f(r,{0,0,650,430},14);f(r,{62,82,420,34},215);f(r,{62,135,300,12},115);f(r,{62,160,470,10},88);f(r,{62,180,430,10},78);for(int i=0;i<2;i++){SDL_Rect q{62+i*190,286,170,48};if(i==s.detailsAction)f(r,{q.x-4,q.y-4,q.w+8,q.h+8},245);f(r,q,i?64:210);}f(r,{62,475,200,15},125);for(int i=0;i<4;i++)f(r,{62+i*290,510,260,145},48+i*7);}
static void player(SDL_Renderer*r,const AppState&s){f(r,{48,42,360,16},115);f(r,{64,620,1152,5},95);f(r,{64,620,360,5},220);f(r,{64,646,48,32},s.playerPaused?220:115);f(r,{124,654,150,8},105);f(r,{1040,654,176,8},85);}
void render(SDL_Renderer*r,const AppState&s){SDL_SetRenderDrawColor(r,8,8,10,255);SDL_RenderClear(r);if(s.view==View::Profiles)profiles(r,s);else if(s.view==View::Player)player(r,s);else if(s.view==View::Details)details(r,s);else if(s.screen==Screen::Search)search(r,s);else browse(r,s);}
}
